import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { abs } from "./site";

/**
 * Agent instructions: every page has a prompt written to a coding agent, generated by
 * `pnpm llms` (scripts/lib/agent-prompts.ts) into public/agents. The prompt of a page is at
 * the page's path plus `.md`; the home page's is /agents/index.md. Server only.
 */
const DIR = join(process.cwd(), "public");

export interface AgentPromptRef {
  /** Site-relative URL of the plain-text prompt, e.g. /agents/atoms/bar-chart.md */
  href: string;
  /** The same as an absolute URL, to hand to an agent. */
  url: string;
  /** What "Open in Claude" and "Open in ChatGPT" start the chat with. */
  prefill: string;
}

/** Longest prompt, URL-encoded, that is sent whole in a chat URL. Longer ones are sent as their address. */
const MAX_PREFILL = 6000;

const hrefOf = (path: string) => `/agents${path === "/" ? "/index" : path.replace(/\/$/, "")}.md`;

export function agentPromptText(path: string): string | undefined {
  const file = join(DIR, hrefOf(path));
  return existsSync(file) ? readFileSync(file, "utf8") : undefined;
}

/** The prompt of a page, or undefined when it has none (an example whose title has no slug of its own). */
export function findAgentPrompt(path: string): AgentPromptRef | undefined {
  const text = agentPromptText(path);
  if (text === undefined) return undefined;
  const href = hrefOf(path);
  const url = abs(href);
  return { href, url, prefill: encodeURIComponent(text).length <= MAX_PREFILL ? text.trim() : `Read ${url} and follow the instructions in it.` };
}

/** The prompt of a page that must have one. Fails the build with the command that fixes it. */
export function agentPrompt(path: string): AgentPromptRef {
  const ref = findAgentPrompt(path);
  if (!ref) throw new Error(`No agent instructions for ${path}: public${hrefOf(path)} is missing. Run \`pnpm llms\` from the repository root.`);
  return ref;
}

/** A guide's long Markdown reference, when scripts/llms-guides has one of the same name. */
export function guideMarkdown(slug: string): string | undefined {
  const href = `/llms/guides/${slug}.md`;
  return slug && existsSync(join(DIR, href)) ? href : undefined;
}
